-- Migration 002 — purchase_orders (Production Planner, spec B8.2)
-- Modelled from PO_MASTER (270 rows, 114 cols). We store ONLY the stored *inputs* +
-- manual *overrides* + *assigned* milestone amounts. Everything name-tagged as derived
-- (supplier:* / branch:* rollups, flexport_*, *_final, *_estimation, *_calculated,
-- filter_*, action_*, last_modified_*) is recomputed by the app and NOT stored here.
--
-- Date override pattern (spec B8.2 "M > FLEX > FUL"): we store the manual *_overide and the
-- raw inputs; the app derives *_final = override ▸ flexport ▸ calculated at read time.
--
-- HOW TO APPLY: tested on Ben's sandbox; BEN runs this on live himself. DDL + seed in one file.

create table if not exists planner.purchase_orders (
  po                          text primary key,            -- e.g. PO-55USXR1
  supplier_name               text,                        -- raw "Supplier" (e.g. "XR Textile")
  supplier_id                 bigint references planner.suppliers(id),  -- resolved by name (below)
  status                      text,                        -- FUTURE / ... (270 filled)
  shipment_ref                text,                        -- SHIPMENT (often = po for single-PO ships)
  prod_no                     text,                        -- PROD# (project, e.g. P55)
  batch_id                    text,
  batch_date                  date,
  branch                      text,                        -- destination branch (e.g. "US Geneva","CA FBA")
  client                      text,                        -- CLIENT (B2B; empty today)
  deposit_ref                 text,                        -- DEPOSIT link -> deposits.reference
  erp_po                      text,                        -- ERP_PO (Fulfil/Cin7; empty today, spec B8.2)
  notes                       text,

  -- Shipping
  ship_type                   text,                        -- sea / air (input)
  ship_type_overide           text,
  sea_lead_time_days          int,
  country_code                text,                        -- from country_code_overide
  first_release_window        text,                        -- batch release window (input)

  -- Dates: raw inputs + manual overrides (FLEX/calculated come from app)
  start_production            date,
  end_production_overide      date,
  days_production_overide     int,
  warehouse_complete_date     date,
  landing_date_overide        date,
  delivery_date_overide       date,
  balance_due_date_overide    date,
  supplier_ship_date          date,

  -- Money / payment inputs (assigned = manual lock over the calculated milestone)
  supplier_invoice_total      numeric(14,2),               -- actual invoice (empty today)
  order_value_estimation      numeric(14,2),               -- source's working estimate (kept for ref)
  deposit_fx_rate             numeric(12,5),
  credit_fee_assigned         numeric(14,2),
  pay_start_deposit_assigned  numeric(14,2),
  pay_start_deposit_date      date,
  pay_completion_assigned     numeric(14,2),               -- pay_completion_deposit_assigned
  pay_completion_date         date,                        -- pay_completion_deposit_date
  pay_balance_1_amount        numeric(14,2),
  pay_balance_1_date          date,                        -- pay_balance_1_deposit_date

  created_at                  timestamptz not null default now(),
  updated_at                  timestamptz not null default now()
);

create index if not exists purchase_orders_supplier_idx on planner.purchase_orders(supplier_id);
create index if not exists purchase_orders_prod_no_idx   on planner.purchase_orders(prod_no);
create index if not exists purchase_orders_status_idx    on planner.purchase_orders(status);

comment on table planner.purchase_orders is 'PO headers (inputs only) from PO_MASTER; derived fields recomputed in app (spec B8.2).';

-- ── Seed (generated from PO_MASTER; dups removed keep-first, derived/empty cols dropped) ──
insert into planner.purchase_orders (po,supplier_name,status,shipment_ref,prod_no,batch_id,batch_date,branch,client,deposit_ref,erp_po,notes,ship_type,ship_type_overide,sea_lead_time_days,country_code,first_release_window,start_production,end_production_overide,days_production_overide,warehouse_complete_date,landing_date_overide,delivery_date_overide,balance_due_date_overide,supplier_ship_date,supplier_invoice_total,order_value_estimation,deposit_fx_rate,credit_fee_assigned,pay_start_deposit_assigned,pay_start_deposit_date,pay_completion_assigned,pay_completion_date,pay_balance_1_amount,pay_balance_1_date) values
